describe('decimal.digit', () => {
    it('accepts every example', () => {
        expect(DecimalDigit.parse(0)).toBe(0);
        expect(DecimalDigit.parse(3)).toBe(3);
        expect(DecimalDigit.parse(9)).toBe(9);
    });
    it('rejects every counterexample', () => {
        expect(DecimalDigit.safeParse(-1).success).toBe(false);
        expect(DecimalDigit.safeParse(10).success).toBe(false);
        expect(DecimalDigit.safeParse('3').success).toBe(false);
        // 3.0 is the integer after JSON.parse; the serialized form is not.
    });
});

